WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_reading_logic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '逻辑梳理', 'kp-sl-reading-logic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "逻辑梳理：构建材料树"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "几千字的材料，在脑子里必须变成一张清晰的思维导图（问题-原因-对策）。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、理清材料的三大逻辑"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "并列逻辑：材料第一、二、三段分别讲了北京、上海、广州的做法。这叫并列。答题时必须分条列点，不能遗漏任何一个城市的做法。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "递进逻辑：第一段讲水污染，第二段讲水污染导致农作物死亡，第三段讲水污染引发农民致贫。这是“问题->影响”的递进。答题时要理清因果链条。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "对立逻辑：前三段讲过去的乱象，后三段讲现在的治理成效。这是对比。答题要注意时间节点的切换。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标注法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在试卷的材料旁边，用简写标出每段的属性：【问】代表问题，【因】代表原因，【果】代表影响，【策】代表对策。做题时直接按标签去对应的段落找答案。"}]}]}$$ AS jsonb), NULL, '逻辑梳理的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "阅读理解", "逻辑脉络"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_reading_logic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
